local config = {
  ui_story_32270401_1_dialog_content = "Pacote para você, Rachel—",
  ui_story_32270401_2_dialog_content = "Você... veio muito mais cedo do que eu esperava.",
  ui_story_32270401_3_dialog_content = "(Hã? Eu imaginei, ou Rachel escondeu algo agora mesmo?)",
  ui_story_32270401_4_dialog_content = "Uau, o que são todas essas peças? Você está... Ah, desculpe, eu não queria me intrometer...",
  ui_story_32270401_5_dialog_content = "Tudo bem, não há nada para esconder de você aqui, na maioria das vezes.",
  ui_story_32270401_6_dialog_content = "De qualquer forma, eu trouxe o seu pacote. Huh? Isso é algum tipo de remédio?",
  ui_story_32270401_7_dialog_content = "Você não está doente, está?",
  ui_story_32270401_8_dialog_content = "Não se preocupe, eu não estou. Dê uma olhada mais de perto.",
  ui_story_32270401_9_dialog_content = "\"30-em-1 Comprimidos Nutricionais\"? Urgh, eles cheiram pior do que a comida do Vice...",
  ui_story_32270401_10_dialog_content = "O cheiro não é importante. Esses comprimidos nutritivos são realmente muito úteis.",
  ui_story_32270401_11_dialog_content = "Composto por trinta ingredientes diferentes, um comprimido contém o valor nutricional completo de um jantar saudável e equilibrado.",
  ui_story_32270401_12_dialog_content = "Eles me poupam muito tempo, especialmente quando estou muito ocupado. Acabei de terminar meu último suprimento, e a União Mensageira entregou outro imediatamente. Eles são tão confiáveis como sempre—",
  ui_story_32270401_13_dialog_content = "Espere! Você... Você tem comido apenas isso nos últimos dias? Você não comeu nenhuma comida de verdade?",
  ui_story_32270401_14_dialog_content = "Nenhuma mesmo. Com o valor funcional e nutricional desses comprimidos, não há necessidade de ingerir qualquer sustento adicional.",
  ui_story_32270401_15_dialog_content = "\"Ingerir sustento\", ela diz... Você não pode simplesmente pular refeições assim, Rachel!",
  ui_story_32270401_16_dialog_content = "A comida tem muitos outros benefícios além da nutrição, você sabe.",
  ui_story_32270401_17_dialog_content = "Como assim?",
  ui_story_32270401_18_dialog_content = "B-Bem, comer comida deliciosa pode ser realmente prazeroso e relaxante, especialmente quando você come com amigos...",
  ui_story_32270401_19_dialog_content = "Entendo seu ponto de vista.",
  ui_story_32270401_20_dialog_content = "(Com certeza não parece ser isso!)",
  ui_story_32270401_21_dialog_content = "... Agora que penso nisso, faz dias desde a última vez que te vi no refeitório.",
  ui_story_32270401_22_dialog_content = "E ainda assim eu não percebi nada de errado... Isso é uma falha minha como seu anfitrião.",
  ui_story_32270401_23_dialog_content = "Já é difícil o suficiente para você tirar um tempo de folga, e você ainda escolheu passar suas férias a bordo do Colossus...",
  ui_story_32270401_24_dialog_content = "Não há necessidade de se sentir tão desanimado com isso.",
  ui_story_32270401_25_dialog_content = "Ah, desculpe. Eu não estava te culpando ou algo assim, eu só queria dizer...",
  ui_story_32270401_26_dialog_content = "Você é um bom anfitrião e tenho passado momentos maravilhosos aqui no Colossus.",
  ui_story_32270401_27_dialog_content = "S-Sério?",
  ui_story_32270401_28_dialog_content = "... Que reviravolta rápida.",
  ui_story_32270401_29_dialog_content = "Está decidido! Vou te oferecer uma boa e quente refeição em Umbraton esta noite!",
  ui_story_32270401_30_dialog_content = "Isso não será necessário. Ainda tenho uma série de questões mecânicas importantes para resolver, e-",
  ui_story_32270401_31_dialog_content = "Não se preocupe, vai ficar tudo bem! Ficar se preocupando com detalhes só vai complicar as coisas, então vamos simplesmente fazer isso!",
  ui_story_32270401_32_dialog_content = "Hoje à noite às sete horas em Umbraton! Esteja lá!",
  ui_story_32270401_33_dialog_content = "...",
  ui_story_32270401_34_dialog_content = "(Estou um pouco nervoso... Fui muito insistente quando convidei Rachel para jantar esta noite? E se ela não aparecer?)",
  ui_story_32270401_35_dialog_content = "<color=#e8d9bb>Um relógio de pêndulo no canto do restaurante marca sete horas.</color>",
  ui_story_32270401_36_dialog_content = "Desculpe pela demora, Celestita Um.",
  ui_story_32270401_37_dialog_content = "Rachel! Você apareceu exatamente às sete horas!",
  ui_story_32270401_38_dialog_content = "Claro. Você nunca deve se atrasar para uma missão.",
  ui_story_32270401_39_dialog_content = "Uma missão?",
  ui_story_32270401_40_dialog_content = "... É apenas uma figura de linguagem! Definitivamente não estou tratando este jantar como uma missão ou algo assim.",
  ui_story_32270401_41_dialog_content = "No entanto, tenho um assunto urgente para tratar durante o jantar de hoje à noite.",
  ui_story_32270401_42_dialog_content = "Entendi... Desculpe por te atrapalhar quando você está tão ocupado...",
  ui_story_32270401_43_dialog_content = "Aqui está a sua limonada, senhorita.",
  ui_story_32270401_44_dialog_content = "... Eu pensei que você pudesse estar com sede, então eu pedi isso para você.",
  ui_story_32270401_45_dialog_content = "Eu agradeço.",
  ui_story_32270401_46_dialog_content = "(Uau! Ela bebeu tudo de uma só vez!)",
  ui_story_32270401_47_dialog_content = "Assim como um pouco de pão e manteiga de cortesia.",
  ui_story_32270401_48_dialog_content = "Eu agradeço.",
  ui_story_32270401_49_dialog_content = "(Ela acabou com o pão em uma única mordida também! Não sobrou nem um traço de manteiga no prato!)",
  ui_story_32270401_50_dialog_content = "(E agora ela está sentada ereta com as mãos no colo, como se nada tivesse acontecido...)",
  ui_story_32270401_51_dialog_content = "Uh... Rachel?",
  ui_story_32270401_52_dialog_content = "Sim? O que é, Celestita Um?",
  ui_story_32270401_53_dialog_content = "Não estamos em uma base militar, você sabe disso, certo?",
  ui_story_32270401_54_dialog_content = "Você não está sendo cronometrado aqui, então apenas aproveite o seu tempo e curta a comida, ok?",
  ui_story_32270401_55_dialog_content = "Hã? Não entendo. Por que eu levaria meu tempo quando posso terminar minha refeição em apenas alguns segundos?",
  ui_story_32270401_56_dialog_content = "Porque permite que você aprecie realmente o sabor da comida.",
  ui_story_32270401_57_dialog_content = "Algo tão insignificante quanto o sabor não deve ter prioridade sobre a eficiência—",
  ui_story_32270401_58_dialog_content = "... Desculpe, talvez \"insignificante\" seja um pouco duro. O que eu quis dizer é—",
  ui_story_32270401_59_dialog_content = "... Tudo bem, eu entendo. Você disse que está em uma missão, afinal... Desculpe.",
  ui_story_32270401_60_dialog_content = "Provavelmente tenho muito tempo livre em mãos, então é fácil para mim falar sobre coisas assim...",
  ui_story_32270401_61_dialog_content = "Haha... Por que não damos uma olhada no cardápio? Ainda não pedimos nenhum prato principal.",
  ui_story_32270401_62_dialog_content = "Minha missão não é o que você pensa que é, PlayerName. A-A verdade é...",
  ui_story_32270401_63_dialog_content = "Eu... Eu quero te dar algo! Aqui—",
  ui_story_32270401_64_dialog_content = "Miau!",
  ui_story_32270401_65_dialog_content = "Uau, de onde veio esse gato?",
  ui_story_32270401_66_dialog_content = "Miau, miau!",
  ui_story_32270401_67_dialog_content = "Oh não... Não o deixe escapar!",
  ui_story_32270401_68_dialog_content = "Hã?",
  ui_story_32270401_69_dialog_content = "Depois daquele gato! Ele roubou seu... Quer dizer, ele roubou <color=#FFB400>algo muito importante</color>!",
  ui_story_32270401_70_dialog_content = "Bem ali!",
  ui_story_32270401_71_dialog_content = "Segure-o aí, gato!",
  ui_story_32270401_72_dialog_content = "Miau!",
  ui_story_32270401_73_dialog_content = "Está subindo na parede de novo! Urgh, não somos páreo para as habilidades de escalada de um gato...",
  ui_story_32270401_74_dialog_content = "Perseguir assim não vai funcionar... É quase impossível acompanhar um gato na cidade à noite. Precisamos pensar em uma estratégia.",
  ui_story_32270401_75_dialog_content = "Uma estratégia, hein? Deixe-me pensar... Eu poderia tentar sentir a localização.",
  ui_story_32270401_76_dialog_content = "Perfeito. Você me diz a localização, e eu farei meus Caçadores de Águia perseguirem até um beco sem saída. Uma vez que esteja encurralado—",
  ui_story_32270401_77_dialog_content = "Vou pular e pegá-lo!",
  ui_story_32270401_78_dialog_content = "Você entende rápido, Celestita Um. Vamos começar a operação!",
  ui_story_32270401_79_dialog_content = "No telhado!",
  ui_story_32270401_80_dialog_content = "Miau!",
  ui_story_32270401_81_dialog_content = "Ele pulou para o muro ali!",
  ui_story_32270401_82_dialog_content = "Miau!",
  ui_story_32270401_83_dialog_content = "Miau... Miau? Miau, miau...",
  ui_story_32270401_84_dialog_content = "Miau, miau!",
  ui_story_32270401_85_dialog_content = "Você não vai escapar!",
  ui_story_32270401_86_dialog_content = "Miau! Miau, miau, miau!",
  ui_story_32270401_87_dialog_content = "Passe para mim, Celestita Um.",
  ui_story_32270401_88_dialog_content = "Desculpe se te assustamos, gatinho.",
  ui_story_32270401_89_dialog_content = "(A voz e a expressão dela de repente se tornaram muito gentis... Eu completamente esqueci deste lado dela.)",
  ui_story_32270401_90_dialog_content = "Que tal alguns arranhões?",
  ui_story_32270401_91_dialog_content = "Miau! Ronronar...",
  ui_story_32270401_92_dialog_content = "(O gato baixou completamente a guarda!)",
  ui_story_32270401_93_dialog_content = "Agora, seja um bom gatinho e fique quieto... Pronto!",
  ui_story_32270401_94_dialog_content = "Bom trabalho, Rachel! Então o que exatamente é essa \"coisa muito importante\"?",
  ui_story_32270401_95_dialog_content = "Eu-É...",
  ui_story_32270401_96_dialog_content = "<color=#e8d9bb>*estômago roncando*</color>",
  ui_story_32270401_97_dialog_content = "!",
  ui_story_32270401_98_dialog_content = "Ahh, agora que terminamos de correr atrás daquele gato, percebo o quanto estou com fome...",
  ui_story_32270401_99_dialog_content = "Desculpe, isso é tudo culpa minha. Não conseguimos fazer nosso pedido de comida mais cedo...",
  ui_story_32270401_100_dialog_content = "Espere, acho que ainda tenho algo... Aha, aqui está! Um sanduíche de queijo!",
  ui_story_32270401_101_dialog_content = "O pão está um pouco amassado, mas... Sim! Ainda tem um gosto ótimo!",
  ui_story_32270401_102_dialog_content = "Miau! Miau, miau!",
  ui_story_32270401_103_dialog_content = "Você também está com fome, pequenino? Aqui, podemos compartilhar.",
  ui_story_32270401_104_dialog_content = "Miau, miau!",
  ui_story_32270401_105_dialog_content = "Parece que ele realmente gosta de você, hein? Venha aqui, gatinho, eu tenho seu pedaço bem aqui.",
  ui_story_32270401_106_dialog_content = "Eu sei que é fofo e tudo mais, mas não dê todo o seu sanduíche, Rachel. Não vai sobrar nada para você!",
  ui_story_32270401_107_dialog_content = "Eu-Eu não pretendia... De qualquer forma, vamos comer—",
  ui_story_32270401_108_dialog_content = "... É delicioso!",
  ui_story_32270401_109_dialog_content = "Miau! Miau!",
  ui_story_32270401_110_dialog_content = "O que, você quer mais? Para um pequeno, você tem um grande apetite. Isso é suficiente para você?",
  ui_story_32270401_111_dialog_content = "Hehehe...",
  ui_story_32270401_112_dialog_content = "Qual a graça?",
  ui_story_32270401_113_dialog_content = "Lembro-me de alguém me dizendo para não alimentar o gato, e agora ele está dando toda a sua comida para ele.",
  ui_story_32270401_114_dialog_content = "I-Isso é só porque nós o assustamos tanto agora! Além disso, eu ainda tenho muito! Vê?",
  ui_story_32270401_115_dialog_content = "... Você sempre carrega tanta comida seca consigo?",
  ui_story_32270401_116_dialog_content = "Você não faz ideia do que eu passei, Rachel...",
  ui_story_32270401_117_dialog_content = "He...",
  ui_story_32270401_118_dialog_content = "(Ela está rindo de novo... Sinto que ela riu mais vezes esta noite do que nunca antes.)",
  ui_story_32270401_119_dialog_content = "Eu... Eu acho que entendi agora. Quando as pessoas têm algo delicioso para comer, elas demoram porque não querem que a experiência acabe.",
  ui_story_32270401_120_dialog_content = "E é só quando estão felizes que podem realmente apreciar o sabor da comida.",
  ui_story_32270401_121_dialog_content = "Neste momento, o sanduíche na minha mão está especialmente delicioso.",
  ui_story_32270401_122_dialog_content = "(Não consigo acreditar que ela disse tudo isso com um olhar tão feliz no rosto. Isso é totalmente fora do personagem...)",
  ui_story_32270401_123_dialog_content = "Hmm? Por que seu rosto está tão vermelho? Será que você não está com exaustão de calor de tanto correr?",
  ui_story_32270401_124_dialog_content = "N-N-Não é nada! Hahaha... Não pode ser tão bom, certo? Afinal, é apenas um sanduíche!",
  ui_story_32270401_125_dialog_content = "Não coma demais, ok? Ainda podemos voltar ao restaurante e pedir nossa comida.",
  ui_story_32270401_126_dialog_content = "Sem necessidade. Eu já tive o jantar mais delicioso, tudo graças ao meu maravilhoso anfitrião.",
  ui_story_32270401_127_dialog_content = "Aqui, PlayerName... Esta medalha é para você.",
  ui_story_32270401_128_dialog_content = "\"Melhor Anfitrião do Mundo\"? É lindo... Espera, você está me dando isso?",
  ui_story_32270401_129_dialog_content = "Sim. Espero que você não se importe, mas eu mesmo fiz.",
  ui_story_32270401_130_dialog_content = "Ah! Então isso é o que você estava escondendo quando eu vim ao seu quarto mais cedo hoje! É também a \"coisa muito importante\" que nosso pequeno amigo tentou roubar...",
  ui_story_32270401_131_dialog_content = "Miau!",
  ui_story_32270401_132_dialog_content = "Isso mesmo... Quando me convidou para jantar, achei que era a ocasião perfeita para te dar isto.",
  ui_story_32270401_133_dialog_content = "Todos os dias que passei no Soroz são tão pacíficos e divertidos.",
  ui_story_32270401_134_dialog_content = "Eu experimento um prazer diferente de tudo que já senti antes, e é tudo graças a você, PlayerName.",
  ui_story_32270401_135_dialog_content = "Sem um anfitrião incrível como você, eu nunca teria tido umas férias tão maravilhosas—",
  ui_story_32270401_136_dialog_content = "... Nem teria experimentado a verdadeira alegria da comida pela primeira vez na minha vida.",
  ui_story_32270401_137_dialog_content = "Obrigado. Sempre lembrarei de cada momento que passei a bordo do Colossus.",
  ui_story_32270401_138_dialog_content = "Rachel!",
  ui_story_32270401_139_dialog_content = "Tudo bem, então está decidido! A partir de amanhã, o maior apresentador do mundo vai mostrar a você todas as coisas incríveis que o Astra tem a oferecer!",
  ui_story_32270401_140_dialog_content = "H-Huh?",
  ui_story_32270401_141_dialog_content = "E começaremos com as corridas no Deserto Rediesel! Segure-se firme—",
  ui_story_32270401_142_dialog_content = "Espere, apenas se acalme um pouco!",
  ui_story_32270601_1_dialog_content = "<color=#e8d9bb>Respingo... Respingo...</color>",
  ui_story_32270601_2_dialog_content = "Isso é estranho...",
  ui_story_32270601_3_dialog_content = "Por que a praia aqui não é animada de jeito nenhum?",
  ui_story_32270601_4_dialog_content = "A praia não deveria estar cheia de pessoas nesta época do ano...?",
  ui_story_32270601_5_dialog_content = "(Poderia ser... Eu entendi mal as intenções de Reinhardt?)",
  ui_story_32270601_6_dialog_content = "Agora eu tenho uma \"missão\" que quero confiar a você, PlayerName.",
  ui_story_32270601_7_dialog_content = "Claro, tem uma recompensa.",
  ui_story_32270601_8_dialog_content = "Não somos amigos...? Por que tão formal de repente, está me deixando um pouco nervoso...",
  ui_story_32270601_9_dialog_content = "Haha! Não é uma missão particularmente difícil, mas...",
  ui_story_32270601_10_dialog_content = "Preciso que você acompanhe Rachel à praia e garanta que ela se divirta. É só isso. Estou contando com você.",
  ui_story_32270601_11_dialog_content = "Celestita Um... Ah, não, eu deveria te chamar de PlayerName.",
  ui_story_32270601_12_dialog_content = "Obrigado por tirar um tempo para vir e se juntar a mim nesta missão.",
  ui_story_32270601_13_dialog_content = "S... Sério uma missão...?",
  ui_story_32270601_14_dialog_content = "Mas a roupa de Rachel hoje... não parece que ela está em uma missão?",
  ui_story_32270601_15_dialog_content = "Isso... Eu fui para Umbraton especificamente para infiltrar a praia.",
  ui_story_32270601_16_dialog_content = "O alto Presidente da Guilda escolheu pessoalmente um maiô para mim.",
  ui_story_32270601_17_dialog_content = "Ela disse que é o item sazonal mais recente, garantido para se misturar perfeitamente com o clima da praia, mas...",
  ui_story_32270601_18_dialog_content = "É a primeira vez que você percebe... quão embaraçoso é usar um maiô?",
  ui_story_32270601_19_dialog_content = "(O alto presidente da guilda, poderia ser a Senhora Sheol...)",
  ui_story_32270601_20_dialog_content = "(Esse maiô... É definitivamente o estilo que ela recomendaria...)",
  ui_story_32270601_21_dialog_content = "Não se envergonhe, você fica muito bonita nisso, Rachel.",
  ui_story_32270601_22_dialog_content = "Não há maiô nesta praia mais bonito que o seu!",
  ui_story_32270601_23_dialog_content = "Não tem... mais ninguém aqui, certo...",
  ui_story_32270601_24_dialog_content = "*Tosse* Na verdade, eu estava me perguntando por que não há mais ninguém aqui...",
  ui_story_32270601_25_dialog_content = "Hmm, parece ser uma área deserta.",
  ui_story_32270601_26_dialog_content = "T-Terra de ninguém?!",
  ui_story_32270601_27_dialog_content = "Eu também acabei de usar um drone para explorar o terreno costeiro e cheguei a essa conclusão.",
  ui_story_32270601_28_dialog_content = "O Grande Marechal especificamente me enviou de férias para este lugar, ele provavelmente ainda espera que eu possa produzir um relatório de pesquisa.",
  ui_story_32270601_29_dialog_content = "As palavras do Grande Marechal...",
  ui_story_32270601_30_dialog_content = "Não, não, não, ela definitivamente quer que você aproveite suas férias, é por isso que ela te trouxe aqui!",
  ui_story_32270601_31_dialog_content = "É mesmo?",
  ui_story_32270601_32_dialog_content = "Se realmente é uma férias, eu não sei o que devo fazer.",
  ui_story_32270601_33_dialog_content = "Ao contrário, continuar a realizar missões dá uma sensação de conforto e facilidade.",
  ui_story_32270601_34_dialog_content = "Se ao menos houvesse gatinhos na praia...",
  ui_story_32270601_35_dialog_content = "Uh... Se estamos de férias, especialmente na praia, na verdade há muitas coisas que podemos fazer...",
  ui_story_32270601_36_dialog_content = "Falando nisso, eu estive curioso por um tempo, PlayerName, você está carregando uma bolsa grande...",
  ui_story_32270601_37_dialog_content = "Este é o local onde o item da missão é armazenado?",
  ui_story_32270601_38_dialog_content = "Para colocar com precisão... Eu acho que sim!",
  ui_story_32270601_39_dialog_content = "<color=#e8d9bb>Clink, clink!</color>",
  ui_story_32270601_40_dialog_content = "Bola de treinamento físico, pistola de simulação de batalha e fruta hidratante para alívio do calor?",
  ui_story_32270601_41_dialog_content = "Se especularmos com base nisso, a missão de PlayerName deveria ser—",
  ui_story_32270601_42_dialog_content = "*Tosse*... É vôlei de praia, pistolas d'água e melancias!",
  ui_story_32270601_43_dialog_content = "Para ser preciso, estes são todos os itens essenciais para umas férias na praia!",
  ui_story_32270601_44_dialog_content = "Então, PlayerName, você já havia decidido se juntar a mim nas férias antes?",
  ui_story_32270601_45_dialog_content = "Afinal, é verão... a praia... não importa como você pense sobre isso, tem que ser férias, certo!?",
  ui_story_32270601_46_dialog_content = "Isso é tão típico de você, PlayerName. Se não fosse por você, eu poderia ter entendido mal as intenções do Grande Marechal.",
  ui_story_32270601_47_dialog_content = "Com base na sua experiência, em qual atividade devemos nos envolver agora?",
  ui_story_32270601_48_option_content = "Que tal jogarmos um pouco de vôlei de praia?",
  ui_story_32270601_49_dialog_content = "Vôlei... É um esporte que nunca encontrei antes.",
  ui_story_32270601_50_dialog_content = "Se você escolher isso, temo que terá que praticar comigo, PlayerName.",
  ui_story_32270601_51_dialog_content = "Então, eu realmente prefiro pistolas de água...",
  ui_story_32270601_52_option_content = "Que tal brincarmos com pistolas d'água?",
  ui_story_32270601_53_dialog_content = "Pistola de água? É bastante semelhante à arma que tenho usado.",
  ui_story_32270601_54_dialog_content = "Até mesmo o efeito silenciador está além de qualquer reprovação.",
  ui_story_32270601_55_dialog_content = "Mas é um pouco injusto com PlayerName...",
  ui_story_32270601_56_dialog_content = "Espere, espere, espere, espere, nós realmente temos que competir?!",
  ui_story_32270601_57_dialog_content = "Por favor, certifique-se de ver este evento como uma competição.",
  ui_story_32270601_58_dialog_content = "Se eu competisse contra você, PlayerName, eu poderia aprender muito.",
  ui_story_32270601_59_dialog_content = "(Sinto que Rachel ainda não está se soltando... Será porque ela raramente faz uma pausa...?)",
  ui_story_32270601_60_dialog_content = "(Eu realmente preciso fazer com que ela se sinta mais envolvida!)",
  ui_story_32270601_61_dialog_content = "Então eu vou primeiro, essa pistola de água premium de alta capacidade é minha!",
  ui_story_32270601_62_dialog_content = "Sinta-se à vontade, PlayerName. Afinal, quando se trata de habilidades de tiro, sou bastante confiante.",
  ui_story_32270601_63_dialog_content = "Hmph, brincar com pistolas d'água não requer necessariamente habilidades de tiro, por exemplo...",
  ui_story_32270601_64_dialog_content = "<color=#e8d9bb>Puf—</color>",
  ui_story_32270601_65_dialog_content = "Está tudo bem em lançar um ataque furtivo, mesmo que não seja honroso.",
  ui_story_32270601_66_dialog_content = "...",
  ui_story_32270601_67_dialog_content = "Eh... Não deveríamos começar a contra-atacar neste ponto?",
  ui_story_32270601_68_dialog_content = "Mas, apontar uma arma para PlayerName, é um pouco...",
  ui_story_32270601_69_dialog_content = "Esta é uma pistola de água, Rachel.",
  ui_story_32270601_70_dialog_content = "E não foi isso que Rachel escolheu? Foi você quem sugeriu a competição, então...",
  ui_story_32270601_71_dialog_content = "<color=#e8d9bb>Sibilo—Sibilo—</color>",
  ui_story_32270601_72_dialog_content = "Então, mesmo que você não contra-ataque, eu não vou parar!",
  ui_story_32270601_73_dialog_content = "Espere, espere!",
  ui_story_32270601_74_dialog_content = "Eu não vou parar até que Rachel admita a derrota!!",
  ui_story_32270601_75_dialog_content = "O perdedor perderá o direito de distribuir melancias, prepare-se!!!",
  ui_story_32270601_76_dialog_content = "Não me importo com a melancia, mas ser o único todo encharcado é bastante constrangedor...",
  ui_story_32270601_77_dialog_content = "Estou prestes a contra-atacar, PlayerName.",
  ui_story_32270601_78_dialog_content = "<color=#e8d9bb>Sss... Sss...</color>",
  ui_story_32270601_79_dialog_content = "Essa arma ...",
  ui_story_32270601_80_dialog_content = "Parece impressionante, mas será que o \"poder\" dele é realmente tão baixo?",
  ui_story_32270601_81_dialog_content = "Eu preciso pensar em algo...",
  ui_story_32270601_82_dialog_content = "Hehe, então não me culpe... Toma essa!",
  ui_story_32270601_83_dialog_content = "<color=#e8d9bb>Sibilo—Sibilo—</color>",
  ui_story_32270601_84_dialog_content = "Uh oh... Fui atingido repetidamente...",
  ui_story_32270601_85_dialog_content = "Então, PlayerName pode ser tão malicioso...?",
  ui_story_32270601_86_dialog_content = "Humph, parece que Rachel ainda não entende o modo de sobrevivência na praia!",
  ui_story_32270601_87_dialog_content = "Bem, eu venci agora! Eu sou a Lenda da Praia, o Rei das Pistolas de Água! Tome isso—",
  ui_story_32270601_88_dialog_content = "<color=#e8d9bb>Puf—</color>",
  ui_story_32270601_89_dialog_content = "Huh... Por que há um arrepio repentino nas minhas costas?",
  ui_story_32270601_90_dialog_content = "PlayerName disse que está tudo bem mesmo que não falemos sobre ética marcial e emboscada, certo?",
  ui_story_32270601_91_dialog_content = "Parece que... eu posso ter dito algo assim, mas...",
  ui_story_32270601_92_dialog_content = "Como você conseguiu me atirar nas costas...?",
  ui_story_32270601_93_dialog_content = "<color=#e8d9bb>PlayerName se vira, ficando cara a cara com três drones equipados com pistolas de água.</color>",
  ui_story_32270601_94_dialog_content = "<color=#e8d9bb>Cercando-o completamente, sem nenhum ponto cego.</color>",
  ui_story_32270601_95_dialog_content = "Então, você não disse que ela não poderia pedir ajuda, certo?",
  ui_story_32270601_96_dialog_content = "Espere, espere, espere, se eu usar o Caçador de Águia...",
  ui_story_32270601_97_dialog_content = "Sem preocupações, todos os módulos de combate foram desligados. Agora estamos no modo de foco em pistolas d'água.",
  ui_story_32270601_98_dialog_content = "Você acabou de dizer \"Isso é apenas uma pistola de água\", não é grande coisa.",
  ui_story_32270601_99_dialog_content = "Por que... Por que não consigo me lembrar de proferir tais palavras irresponsáveis?",
  ui_story_32270601_100_dialog_content = "Ataque de garra!",
  ui_story_32270601_101_dialog_content = "<color=#e8d9bb>Sibilo—<size=50>Sibilo, sibilo, sibilo, sibilo, sibilo—!</size></color>",
  ui_story_32270601_102_dialog_content = "A-ajuda!!",
  ui_story_32270601_103_dialog_content = "<color=#e8d9bb>No final, em meio à perseguição do drone e à risada alegre de Rachel...</color>",
  ui_story_32270601_104_dialog_content = "<color=#e8d9bb>\"O Último Celestita\", \"Rei das Pistolas de Água\", \"Lenda da Praia\" — PlayerName.</color>",
  ui_story_32270601_105_dialog_content = "<color=#e8d9bb>Dando as boas-vindas à derrota mais brutal deste verão...</color>"
}
return config
